CREATE TABLE users(user_id INTEGER PRIMARY KEY AUTOINCREMENT, full_name TEXT);
CREATE TABLE admins(admin_id INTEGER PRIMARY KEY AUTOINCREMENT, full_name TEXT, email TEXT, role TEXT DEFAULT 'admin', is_active INT DEFAULT 1);
CREATE TABLE products(product_id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, stock_quantity REAL);
CREATE TABLE orders(order_id INTEGER PRIMARY KEY AUTOINCREMENT, order_number TEXT, user_id INT, customer_name TEXT, customer_phone TEXT, customer_email TEXT DEFAULT '', delivery_method TEXT DEFAULT 'delivery', grand_total REAL, payment_status TEXT DEFAULT 'pending', order_status TEXT DEFAULT 'received', inventory_state TEXT DEFAULT 'deducted', stock_deducted_at TEXT, stock_restored_at TEXT, needs_admin_review INT DEFAULT 0);
CREATE TABLE order_items(order_item_id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INT, product_id INT, product_name TEXT, quantity REAL);
CREATE TABLE payments(payment_id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INT, user_id INT, amount REAL, currency TEXT DEFAULT 'UGX', provider TEXT, phone_number TEXT, method TEXT DEFAULT 'mobile_money', transaction_reference TEXT UNIQUE, status TEXT DEFAULT 'pending', pesajet_transaction_id TEXT UNIQUE, provider_reference TEXT, attempt_count INT DEFAULT 0, api_response TEXT, webhook_status TEXT, webhook_received_at TEXT, failure_reason TEXT, paid_at TEXT, verification_source TEXT, manual_verified_by INT, manual_verified_at TEXT, manual_note TEXT, admin_decision TEXT, admin_decision_by INT, admin_decision_at TEXT, admin_decision_note TEXT, provider_status TEXT, provider_verified_at TEXT, provider_verification_result TEXT, needs_reconciliation INT DEFAULT 0, reconciliation_note TEXT, reconciliation_flagged_at TEXT, reconciliation_resolved_at TEXT, reconciliation_resolved_by INT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TRIGGER pay_upd AFTER UPDATE ON payments WHEN NEW.updated_at = OLD.updated_at BEGIN UPDATE payments SET updated_at = datetime('now') WHERE payment_id = NEW.payment_id; END;
CREATE TABLE payment_webhook_events(webhook_event_id INTEGER PRIMARY KEY AUTOINCREMENT, transaction_id TEXT, event TEXT, reference TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE inventory_logs(log_id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INT, change_qty REAL, reason TEXT, reference TEXT, admin_id INT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE order_admin_actions(action_id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INT, payment_id INT, admin_id INT, action_type TEXT, previous_order_status TEXT, new_order_status TEXT, previous_payment_status TEXT, new_payment_status TEXT, note TEXT, transaction_reference TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE payment_status_history(history_id INTEGER PRIMARY KEY AUTOINCREMENT, payment_id INT, order_id INT, previous_status TEXT, new_status TEXT, source TEXT, admin_id INT, provider_status TEXT, note TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE admin_activity_logs(log_id INTEGER PRIMARY KEY AUTOINCREMENT, admin_id INT, action TEXT, details TEXT);
